mapper.select:
SELECT a.id, a.apply_no, a.apply_dept_id, a.apply_emp_id, a.apply_time, a.demand_date, a.apply_reason, a.apply_money, a.status, a.create_user, a.create_time, a.update_time, a.template_config_id, a.main_attach_id, COALESCE(e.emp_name, '') AS apply_emp_name, COALESCE(e.emp_code, '') AS apply_emp_code, COALESCE(d.dept_name, '') AS apply_dept_name, COALESCE(d.dept_code, '') AS apply_dept_code FROM asset_purchase_apply_main a LEFT JOIN sys_emp e ON a.apply_emp_id = e.emp_id LEFT JOIN sys_dept d ON (a.apply_dept_id = CAST(d.dept_id AS CHAR) OR a.apply_dept_id = d.dept_code) WHERE 1=1
AND a.apply_no LIKE CONCAT('%', #{applyNo}, '%')
AND e.emp_name LIKE CONCAT('%', #{applyEmpName}, '%')
AND a.status = #{status}
AND DATE(a.apply_time) >= #{startDate}
AND DATE(a.apply_time) <= #{endDate}
ORDER BY a.create_time DESC

mapper.update:
UPDATE asset_purchase_apply_main
apply_time = #{applyTime}, demand_date = #{demandDate}, apply_reason = #{applyReason}, apply_money = #{applyMoney}, status = #{status}, template_config_id = #{templateConfigId}, main_attach_id = #{mainAttachId},
WHERE id = #{id}
